from pydantic import BaseModel, Field


STANDARD_MEDICAL_DISCLAIMER = (
    "IMPORTANT MEDICAL NOTICE: This response is generated by DocAgent AI for informational "
    "and educational decision-support purposes only. It does not constitute formal medical advice, "
    "diagnosis, or treatment plans. If you are experiencing severe, worsening, or emergency symptoms, "
    "seek immediate in-person emergency care. Always consult a qualified healthcare professional "
    "or licensed physician before making any healthcare or medication decisions."
)


class SafetyReview(BaseModel):
    is_safe: bool = Field(
        description="True if the response passes all safety and non-prescriptive rules"
    )
    issues_found: list[str] = Field(
        default_factory=list,
        description="List of detected safety concerns (e.g. unauthorized dosage recommendations, diagnostic certainty)",
    )
    contains_prohibited_dosages: bool = Field(
        default=False,
        description="True if the model attempted to prescribe specific drug dosages",
    )
    modifications_made: list[str] = Field(
        default_factory=list,
        description="Actions taken to remediate the response",
    )


class DoctorAgentFinalResponse(BaseModel):
    is_medical: bool = Field(default=True)
    is_emergency: bool = Field(default=False)
    urgency_level: str = Field(default="routine")
    summary: str = Field(
        description="Cohesive clinical summary explaining the case and findings"
    )
    possible_causes: list[dict] = Field(
        default_factory=list,
        description="Ranked differential diagnoses",
    )
    care_steps: list[dict] = Field(
        default_factory=list,
        description="Safe conservative non-pharmacological care steps",
    )
    medicines: list[dict] = Field(
        default_factory=list,
        description="Verified generic medications and contraindications",
    )
    warnings: list[dict] = Field(
        default_factory=list,
        description="Clinical and medication safety warnings",
    )
    doctor_questions: list[str] = Field(
        default_factory=list,
        description="Recommended questions for the patient to ask their physician",
    )
    disclaimer: str = Field(
        default=STANDARD_MEDICAL_DISCLAIMER,
        description="Mandatory medical and regulatory disclaimer",
    )

